window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-58af98add52ef371"]={"versions": [{"id": "FIG-58af98add52ef371", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bitfeld-Layout/Header-Struktur) zur Definition der SOME/IP-SD IPv4 SD Endpoint Option im Rahmen des SOME/IP Service Discovery Protokolls (AUTOSAR Foundation / Classic & Adaptive Platform). Das Format spezifiziert die serielle Repräsentation eines dedizierten IPv4-Dienstendpunkts der Service-Discovery-Instanz innerhalb des Options-Bereichs einer SOME/IP-SD-Nachricht über einer 32-Bit-Rasterstruktur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Option besteht aus einem 32-Bit-Raster mit folgenden Entitäten und Feldern:</p>\n<ul class=\"fig-list\">\n<li><strong>Length</strong> (Bit 0–15, 16 Bit): Konstantenwert <code>0x0009</code> (9 Byte Nutzlänge der Option abzüglich des Length-Feldes selbst).</li>\n<li><strong>Type</strong> (Bit 16–23, 8 Bit): Options-Typ-Kennung mit dem festen Wert <code>0x24</code> zur Identifikation als IPv4 SD Endpoint Option.</li>\n<li><strong>Reserved</strong> (Bit 24–31, 8 Bit): Erstes Reserviertes Feld mit dem festen Wert <code>0x00</code>.</li>\n<li><strong>IPv4-Address</strong> (Bit 0–31, 32 Bit): 32-Bit IPv4-Adresse der SD-Instanz.</li>\n<li><strong>Reserved</strong> (Bit 0–7, 8 Bit): Zweites Reserviertes Feld mit dem festen Wert <code>0x00</code>.</li>\n<li><strong>L4-Proto</strong> (Bit 8–15, 8 Bit): Transportprotokoll der Schicht 4 (<code>UDP/...</code>).</li>\n<li><strong>Port Number</strong> (Bit 16–31, 16 Bit): Portnummer der SOME/IP-SD-Instanz.</li>\n<li><strong>Covered by Length (incl. Reserved)</strong>: Bemaßungsanzeige am rechten Rand, die den Gültigkeitsbereich des Length-Feldes über die gesamte verbleibende Struktur (ab Bit 16 der ersten Zeile: Type, Reserved, IPv4-Address, Reserved, L4-Proto und Port Number; gesamt 9 Byte) kennzeichnet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Datenstruktur ohne prozeduralen Sequenzablauf. Im Übertragungsablauf serialisiert der Sender (SOME/IP-SD-Instanz oder Proxy) die Option in Big-Endian-Netzwerk-Byte-Order und hängt sie an das SOME/IP-SD-Paket an. Der Empfänger parst das Length-Feld (0x0009), verifiziert den Optionstyp 0x24 und extrahiert IPv4-Adresse, Transportprotokoll (z. B. UDP) sowie Portnummer zur expliziten Adressierung und Zuordnung der SD-Instanz, insbesondere wenn IP-Header-Informationen abweichen oder durch Multicast-Proxys vermittelt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Festlegungen für die Protokollimplementierung:</p>\n<ul class=\"fig-list\">\n<li>Feste Feldwerte müssen exakt eingehalten werden: <code>Length = 0x0009</code>, <code>Type = 0x24</code>, beide <code>Reserved = 0x00</code>.</li>\n<li>Gesamtlänge der Option beträgt exakt 12 Byte (96 Bit) bzw. 9 Byte abgedeckt durch <code>Length</code>.</li>\n<li>Bit-Offsets und Feldgrenzen im 32-Bit-Wort sind strikt einzuhalten (Network Byte Order / Big Endian).</li>\n<li>Die reservierten Felder müssen beim Senden auf <code>0x00</code> gesetzt werden.</li>\n<li>Das Feld <code>L4-Proto</code> codiert das Schicht-4-Transportprotokoll (IANA-Protokollnummer, typischerweise UDP = 0x11).</li>\n</ul>"}, {"id": "FIG-9ef3e0dfa7d4ace3", "releases": ["R1.5.1", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bitfeld-Layout/Header-Struktur) zur Definition der SOME/IP-SD IPv4 SD Endpoint Option im Rahmen des SOME/IP Service Discovery Protokolls (AUTOSAR Foundation / Classic & Adaptive Platform). Das Format spezifiziert die serielle Repräsentation eines dedizierten IPv4-Dienstendpunkts der Service-Discovery-Instanz innerhalb des Options-Bereichs einer SOME/IP-SD-Nachricht über einer 32-Bit-Rasterstruktur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Option besteht aus einem 32-Bit-Raster mit folgenden Entitäten und Feldern:</p>\n<ul class=\"fig-list\">\n<li><strong>Length</strong> (Bit 0–15, 16 Bit): Konstantenwert <code>0x0009</code> (9 Byte Nutzlänge der Option abzüglich des Length-Feldes selbst).</li>\n<li><strong>Type</strong> (Bit 16–23, 8 Bit): Options-Typ-Kennung mit dem festen Wert <code>0x24</code> zur Identifikation als IPv4 SD Endpoint Option.</li>\n<li><strong>Reserved</strong> (Bit 24–31, 8 Bit): Erstes Reserviertes Feld mit dem festen Wert <code>0x00</code>.</li>\n<li><strong>IPv4-Address</strong> (Bit 0–31, 32 Bit): 32-Bit IPv4-Adresse der SD-Instanz.</li>\n<li><strong>Reserved</strong> (Bit 0–7, 8 Bit): Zweites Reserviertes Feld mit dem festen Wert <code>0x00</code>.</li>\n<li><strong>L4-Proto</strong> (Bit 8–15, 8 Bit): Transportprotokoll der Schicht 4 (<code>UDP/...</code>).</li>\n<li><strong>Port Number</strong> (Bit 16–31, 16 Bit): Portnummer der SOME/IP-SD-Instanz.</li>\n<li><strong>Covered by Length (incl. Reserved)</strong>: Bemaßungsanzeige am rechten Rand, die den Gültigkeitsbereich des Length-Feldes über die gesamte verbleibende Struktur (ab Bit 16 der ersten Zeile: Type, Reserved, IPv4-Address, Reserved, L4-Proto und Port Number; gesamt 9 Byte) kennzeichnet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Datenstruktur ohne prozeduralen Sequenzablauf. Im Übertragungsablauf serialisiert der Sender (SOME/IP-SD-Instanz oder Proxy) die Option in Big-Endian-Netzwerk-Byte-Order und hängt sie an das SOME/IP-SD-Paket an. Der Empfänger parst das Length-Feld (0x0009), verifiziert den Optionstyp 0x24 und extrahiert IPv4-Adresse, Transportprotokoll (z. B. UDP) sowie Portnummer zur expliziten Adressierung und Zuordnung der SD-Instanz, insbesondere wenn IP-Header-Informationen abweichen oder durch Multicast-Proxys vermittelt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Festlegungen für die Protokollimplementierung:</p>\n<ul class=\"fig-list\">\n<li>Feste Feldwerte müssen exakt eingehalten werden: <code>Length = 0x0009</code>, <code>Type = 0x24</code>, beide <code>Reserved = 0x00</code>.</li>\n<li>Gesamtlänge der Option beträgt exakt 12 Byte (96 Bit) bzw. 9 Byte abgedeckt durch <code>Length</code>.</li>\n<li>Bit-Offsets und Feldgrenzen im 32-Bit-Wort sind strikt einzuhalten (Network Byte Order / Big Endian).</li>\n<li>Die reservierten Felder müssen beim Senden auf <code>0x00</code> gesetzt werden.</li>\n<li>Das Feld <code>L4-Proto</code> codiert das Schicht-4-Transportprotokoll (IANA-Protokollnummer, typischerweise UDP = 0x11).</li>\n</ul>"}, {"id": "FIG-19244c25e5740fbc", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bitfeld-Layout/Header-Struktur) zur Definition der SOME/IP-SD IPv4 SD Endpoint Option im Rahmen des SOME/IP Service Discovery Protokolls (AUTOSAR Foundation / Classic & Adaptive Platform). Das Format spezifiziert die serielle Repräsentation eines dedizierten IPv4-Dienstendpunkts der Service-Discovery-Instanz innerhalb des Options-Bereichs einer SOME/IP-SD-Nachricht über einer 32-Bit-Rasterstruktur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Option besteht aus einem 32-Bit-Raster mit folgenden Entitäten und Feldern:</p>\n<ul class=\"fig-list\">\n<li><strong>Length</strong> (Bit 0–15, 16 Bit): Konstantenwert <code>0x0009</code> (9 Byte Nutzlänge der Option abzüglich des Length-Feldes selbst).</li>\n<li><strong>Type</strong> (Bit 16–23, 8 Bit): Options-Typ-Kennung mit dem festen Wert <code>0x24</code> zur Identifikation als IPv4 SD Endpoint Option.</li>\n<li><strong>Reserved</strong> (Bit 24–31, 8 Bit): Erstes Reserviertes Feld mit dem festen Wert <code>0x00</code>.</li>\n<li><strong>IPv4-Address</strong> (Bit 0–31, 32 Bit): 32-Bit IPv4-Adresse der SD-Instanz.</li>\n<li><strong>Reserved</strong> (Bit 0–7, 8 Bit): Zweites Reserviertes Feld mit dem festen Wert <code>0x00</code>.</li>\n<li><strong>L4-Proto</strong> (Bit 8–15, 8 Bit): Transportprotokoll der Schicht 4 (<code>UDP/...</code>).</li>\n<li><strong>Port Number</strong> (Bit 16–31, 16 Bit): Portnummer der SOME/IP-SD-Instanz.</li>\n<li><strong>Covered by Length (incl. Reserved)</strong>: Bemaßungsanzeige am rechten Rand, die den Gültigkeitsbereich des Length-Feldes über die gesamte verbleibende Struktur (ab Bit 16 der ersten Zeile: Type, Reserved, IPv4-Address, Reserved, L4-Proto und Port Number; gesamt 9 Byte) kennzeichnet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Datenstruktur ohne prozeduralen Sequenzablauf. Im Übertragungsablauf serialisiert der Sender (SOME/IP-SD-Instanz oder Proxy) die Option in Big-Endian-Netzwerk-Byte-Order und hängt sie an das SOME/IP-SD-Paket an. Der Empfänger parst das Length-Feld (0x0009), verifiziert den Optionstyp 0x24 und extrahiert IPv4-Adresse, Transportprotokoll (z. B. UDP) sowie Portnummer zur expliziten Adressierung und Zuordnung der SD-Instanz, insbesondere wenn IP-Header-Informationen abweichen oder durch Multicast-Proxys vermittelt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Festlegungen für die Protokollimplementierung:</p>\n<ul class=\"fig-list\">\n<li>Feste Feldwerte müssen exakt eingehalten werden: <code>Length = 0x0009</code>, <code>Type = 0x24</code>, beide <code>Reserved = 0x00</code>.</li>\n<li>Gesamtlänge der Option beträgt exakt 12 Byte (96 Bit) bzw. 9 Byte abgedeckt durch <code>Length</code>.</li>\n<li>Bit-Offsets und Feldgrenzen im 32-Bit-Wort sind strikt einzuhalten (Network Byte Order / Big Endian).</li>\n<li>Die reservierten Felder müssen beim Senden auf <code>0x00</code> gesetzt werden.</li>\n<li>Das Feld <code>L4-Proto</code> codiert das Schicht-4-Transportprotokoll (IANA-Protokollnummer, typischerweise UDP = 0x11).</li>\n</ul>"}], "trans": [{"from": "FIG-58af98add52ef371", "to": "FIG-9ef3e0dfa7d4ace3", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9ef3e0dfa7d4ace3", "to": "FIG-58af98add52ef371", "fr": "R1.5.1", "tr": "R17-03_R1.1.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9ef3e0dfa7d4ace3", "to": "FIG-19244c25e5740fbc", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
